    for i,(a,b) in enumerate(items):
        x=8 if i<4 else 176;y=8+(i%4)*52
        o+=f'<rect x="{x}" y="{y}" width="156" height="44" rx="6" class="bx"/>'+T(x+78,y+19,a,'t-s t-b')+T(x+78,y+35,b,'t-s mu')
    return o
