    x=60
    for n,c in ((1,'bx'),(3,'bxa'),(6,'bx')):
        o+=B(x,24,20*n,34,('1' if n==1 else f'{n} байт'),c,'t-s');o+=TL(x+2,74,str(sum([1,3,6][:[1,3,6].index(n)])),'t-s mu');x+=20*n
    o+=T(170,106,'RISC: команда басы = 4 · n, ұзындығы белгілі','t-s mu')
    for i in range(3):
        o+=B(60+80*i,114,80,34,'4 байт','bx' if i!=1 else 'bxa','t-s')+TL(62+80*i,164,str(4*i),'t-s mu')
    return o
