def g_timing():
    X=104;W=48
    o=T(170,14,'Фон Нейман: бір шина — 4 такт','t-s t-b')+TL(6,52,'ортақ шина','t-s mu')
    for i,l in enumerate(('К1','Д1','К2','Д2')):o+=B(X+W*i,34,W-2,26,l,'soft' if l[0]=='К' else 'bxa','t-s')
    o+=T(170,90,'Гарвард: екі шина — 3 такт','t-s t-b')+TL(6,114,'команда шина','t-s mu')+TL(6,144,'деректер шина','t-s mu')
    for i,l in ((0,'К1'),(1,'К2')):o+=B(X+W*i,96,W-2,26,l,'soft','t-s')
    for i,l in ((1,'Д1'),(2,'Д2')):o+=B(X+W*i,126,W-2,26,l,'bxa','t-s')
    o+=A(X,172,X+4*W,172,'ln','hd')+T(X+2*W,188,'уақыт (такт)','t-s mu')
    return o
