def g_amdahl():
    o='<line x1="40" y1="20" x2="40" y2="170" class="ln"/><line x1="40" y1="170" x2="326" y2="170" class="ln"/>'
    for v in (0,5,10):o+=TL(14,174-15*v,str(v),'t-s mu')
    o+='<line x1="40" y1="20" x2="326" y2="20" class="ln dash"/>'+T(290,14,'шек = 10','t-s ac')
    pts=[(50+38*i,170-15*s) for i,(n,s) in enumerate(AM)]
    for (x1,y1),(x2,y2) in zip(pts,pts[1:]):o+=f'<line x1="{x1}" y1="{y1:.1f}" x2="{x2}" y2="{y2:.1f}" class="lna"/>'
    for (x,y),(n,s) in zip(pts,AM):o+=f'<circle cx="{x}" cy="{y:.1f}" r="3" class="hda"/>'+T(x,186,str(n),'t-s mu')
    o+=T(180,202,'ядролар саны N','t-s mu')
    return o
