def g_cmos():
    o=''
    for cx,top,bot,out,cap in ((85,('p-кілт\nқосулы','bxa'),('n-кілт\nөшкен','bx'),'шығыс = 1','кіріс = 0'),(255,('p-кілт\nөшкен','bx'),('n-кілт\nқосулы','bxa'),'шығыс = 0','кіріс = 1')):
        o+=T(cx,12,'+U (қор көзі)','t-s mu')+f'<line x1="{cx}" y1="16" x2="{cx}" y2="28" class="ln"/>'
        o+=B(cx-45,28,90,34,top[0],top[1],'t-s')+f'<line x1="{cx}" y1="62" x2="{cx}" y2="76" class="ln"/>'+TL(cx+8,73,out,'t-s ac')
        o+=B(cx-45,76,90,34,bot[0],bot[1],'t-s')+f'<line x1="{cx}" y1="110" x2="{cx}" y2="122" class="ln"/>'+T(cx,134,'жер (0)','t-s mu')+T(cx,154,cap,'t-s t-b')
    return o
f_cmos=F(S(340,162,g_cmos(),'КМОП инверторы'),'КМОП инверторы: екі транзистор жұбының біреуі қосулы, екіншісі өшкен, сондықтан қор көзінен жерге тұрақты жол жоқ. Жеңілдетілген сұлба: транзистор кілт ретінде көрсетілген. p және n — екі қарама-қарсы транзистор түрі')

