("біркристалды МП","однокристальный МП","single-chip microprocessor",""),
("көпкристалды МП","многокристальный МП","multi-chip microprocessor",""),
("секциялық МП","секционный (разрядно-модульный) МП","bit-slice microprocessor",""),
("көпядролы процессор","многоядерный процессор","multi-core processor",""),
